        _ = &last_event_index;
        var last_event_id: u32 = std.math.maxInt(u32);
        _ = &last_event_id;
        {
            var i: i32 = 0;
            _ = &i;
            const __end_1 = all_events.len;
            while (i < __end_1) : (i += 1) {
                if ((all_events[@as(usize, @intCast(i))].index == last_event_id)) {
                    _ = all_events[@as(usize, @intCast(last_event_index))].merge(all_events[@as(usize, @intCast(i))]);
                    continue;
                }
                last_event_index = i;
                last_event_id = all_events[@as(usize, @intCast(i))].index;
            }
        }
        if ((all_events.len == 0)) {
            return .success;
        }
        all_events = all_events[0..(last_event_index + 1)];
        _ = log("calling onFileUpdate (all_events.len = {d})", .{ all_events.len });
        _ = watcher.writeTraceEvents(all_events, watcher.changed_filepaths[0..(last_event_index + 1)]);
        _ = watcher.onFileUpdate(watcher.ctx, all_events, watcher.changed_filepaths[0..(last_event_index + 1)], watcher.watchlist);
        return .success;
}

pub fn createWatchEvent(event: FileEvent, index: WatchItemIndex) WatchEvent {
        return .{ .op = .{ .delete = (event.action == .Removed), .rename = (event.action == .RenamedOld), .write = (event.action == .Modified) }, .index = index };
}
const OptionalEventIterator = ?EventIterator;
